bool terminal_font_has_glyph(uint32_t codepoint) {
    for (size_t i = 0; i < RANGE_COUNT; i++) {
        if (codepoint >= terminal_ranges[i].start && codepoint <= terminal_ranges[i].end) {
            return true;
        }
    }
    return false;
}

int terminal_char_width(uint32_t codepoint) {
    size_t low  = 0;
    size_t high = sizeof(wide_cells) / sizeof(wide_cells[0]);
    while (low < high) {
        size_t middle = low + (high - low) / 2;
        if (codepoint < wide_cells[middle].start) {
            high = middle;
        } else if (codepoint > wide_cells[middle].end) {
            low = middle + 1;
        } else {
            return 2;
        }
    }
    return 1;
}
